    /**
     * Method to retrieve the Laboratory via an LaboratoryPrimaryKey.
     * @param 	id Long
     * @return 	Laboratory
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Laboratory handle( FindLaboratoryQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getLaboratoryId() );
    }
    
    /**
     * Method to retrieve a collection of all Laboratorys
     *
     * @param	query	FindAllLaboratoryQuery 
     * @return 	List<Laboratory> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Laboratory> handle( FindAllLaboratoryQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindLaboratory,
 * but only if the id matches
 *
 * @param		entity	Laboratory
 */
	protected void emitFindLaboratory( Laboratory entity ) {
		LOGGER.info("handling emitFindLaboratory" );
		
	    queryUpdateEmitter.emit(FindLaboratoryQuery.class,
	                            query -> query.getFilter().getLaboratoryId().equals(entity.getLaboratoryId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllLaboratory
	 * 
	 * @param		entity	Laboratory
	 */
	protected void emitFindAllLaboratory( Laboratory entity ) {
		LOGGER.info("handling emitFindAllLaboratory" );
		
	    queryUpdateEmitter.emit(FindAllLaboratoryQuery.class,
	                            query -> true,
	                            entity);
	}

